// Package policy holds the sealed-egress config (INTERFACES section 12):
// strict parsing, allowlist matching and destination IP classification.
// It has no proxy or DNS dependencies, so the composer can import it to
// build and check egress configs.
package policy

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/netip"
	"os"
	"regexp"
	"sort"
	"strings"
)

// Config is the measured egress config, generated by the composer as CJSON.
type Config struct {
	Listen              *Listen  `json:"listen"`
	UpstreamDNS         []string `json:"upstreamDns"`
	Callers             []Caller `json:"callers"`
	AllowedPrivateCIDRs []string `json:"allowedPrivateCidrs"`
	StatsReaders        []string `json:"statsReaders"`
}

// Listen holds listen addresses as "host:port" (host empty or an IP).
type Listen struct {
	Proxy string `json:"proxy"`
	DNS   string `json:"dns"`
	Stats string `json:"stats"`
}

// Caller is one container, identified by its fixed source IP.
type Caller struct {
	Name  string   `json:"name"`
	IP    string   `json:"ip"`
	Allow []string `json:"allow"`
	// ProxyAuth makes the source IP alone insufficient: requests must also
	// carry the caller's proxy credential (see package auth). Optional key,
	// present only as true, so configs without it keep their bytes.
	ProxyAuth bool `json:"proxyAuth,omitempty"`
}

// MaxConfigBytes bounds the config file size.
const MaxConfigBytes = 1 << 20

const (
	maxUpstreams = 8
	maxCallers   = 256
	maxEntries   = 1024
)

// UnknownCaller is the stats bucket for sources that are not a configured
// caller. Parentheses keep it apart from any valid caller name.
const UnknownCaller = "(unknown)"

var callerNamePattern = regexp.MustCompile(`^[a-z0-9][a-z0-9-]{0,62}$`)

var requiredKeys = map[string][]string{
	"":       {"allowedPrivateCidrs", "callers", "listen", "statsReaders", "upstreamDns"},
	"listen": {"dns", "proxy", "stats"},
	"caller": {"allow", "ip", "name"},
}

// optionalCallerKey may appear in a caller, and only with the value true.
const optionalCallerKey = "proxyAuth"

// Load reads and parses the config file at path. The returned bytes are the
// canonical document (without the one trailing newline Parse tolerates), so
// their sha256 matches the composer's.
func Load(path string) (*Config, []byte, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, nil, fmt.Errorf("open egress config: %w", err)
	}
	defer f.Close()
	data, err := io.ReadAll(io.LimitReader(f, MaxConfigBytes+1))
	if err != nil {
		return nil, nil, fmt.Errorf("read egress config: %w", err)
	}
	cfg, err := Parse(data)
	if err != nil {
		return nil, nil, err
	}
	return cfg, trimFinalNewline(data), nil
}

// trimFinalNewline drops one trailing LF. Compose writes inline `configs`
// content verbatim, and a YAML block scalar (`content: |`) ends in one; the
// measured bytes are the compose, not this file, so accepting it costs no
// integrity while rejecting it would stop the whole stack.
func trimFinalNewline(data []byte) []byte {
	return bytes.TrimSuffix(data, []byte("\n"))
}

// Parse decodes canonical JSON config bytes and validates every field. The
// bytes must be canonical CJSON, optionally followed by a single LF.
func Parse(data []byte) (*Config, error) {
	if len(data) > MaxConfigBytes {
		return nil, fmt.Errorf("egress config is larger than %d bytes", MaxConfigBytes)
	}
	data = trimFinalNewline(data)
	if err := CheckCanonical(data); err != nil {
		return nil, fmt.Errorf("egress config: %w", err)
	}
	tree, err := decodeTree(data)
	if err != nil {
		return nil, fmt.Errorf("egress config: %w", err)
	}
	if err := checkKeys(tree); err != nil {
		return nil, fmt.Errorf("egress config: %w", err)
	}
	var cfg Config
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&cfg); err != nil {
		return nil, fmt.Errorf("egress config: %w", err)
	}
	if err := cfg.Validate(); err != nil {
		return nil, err
	}
	return &cfg, nil
}

// checkKeys enforces exact, case-sensitive key sets (encoding/json alone
// matches keys case-insensitively).
func checkKeys(tree any) error {
	top, ok := tree.(map[string]any)
	if !ok {
		return errors.New("top level must be an object")
	}
	if err := exactKeys("", top, requiredKeys[""]); err != nil {
		return err
	}
	if listen, ok := top["listen"].(map[string]any); ok {
		if err := exactKeys("listen", listen, requiredKeys["listen"]); err != nil {
			return err
		}
	}
	if callers, ok := top["callers"].([]any); ok {
		for i, c := range callers {
			obj, ok := c.(map[string]any)
			if !ok {
				return fmt.Errorf("callers[%d] must be an object", i)
			}
			where := fmt.Sprintf("callers[%d]", i)
			want := requiredKeys["caller"]
			if v, present := obj[optionalCallerKey]; present {
				if v != true {
					return fmt.Errorf("%s.%s: must be true when present (omit it for false)", where, optionalCallerKey)
				}
				want = append(append([]string(nil), want...), optionalCallerKey)
				sort.Strings(want)
			}
			if err := exactKeys(where, obj, want); err != nil {
				return err
			}
		}
	}
	return nil
}

func exactKeys(path string, obj map[string]any, want []string) error {
	got := make([]string, 0, len(obj))
	for k := range obj {
		got = append(got, k)
	}
	sort.Strings(got)
	if strings.Join(got, ",") != strings.Join(want, ",") {
		where := path
		if where == "" {
			where = "top level"
		}
		return fmt.Errorf("%s must have exactly the keys [%s], got [%s]", where, strings.Join(want, ", "), strings.Join(got, ", "))
	}
	return nil
}

// Validate checks every field and returns all problems found.
func (c *Config) Validate() error {
	var errs []error
	add := func(format string, args ...any) { errs = append(errs, fmt.Errorf(format, args...)) }

	if c.Listen == nil {
		add("listen: required")
	} else {
		ports := map[string]string{}
		for _, l := range []struct{ name, addr string }{{"proxy", c.Listen.Proxy}, {"dns", c.Listen.DNS}, {"stats", c.Listen.Stats}} {
			port, err := validateListen(l.addr)
			if err != nil {
				add("listen.%s: %v", l.name, err)
				continue
			}
			if port != "0" {
				if other, dup := ports[port]; dup {
					add("listen.%s: port %s is also used by listen.%s", l.name, port, other)
				}
				ports[port] = l.name
			}
		}
	}

	if c.UpstreamDNS == nil {
		add("upstreamDns: required")
	} else if len(c.UpstreamDNS) == 0 || len(c.UpstreamDNS) > maxUpstreams {
		add("upstreamDns: must list 1 to %d servers", maxUpstreams)
	}
	seenUpstream := map[string]bool{}
	for i, u := range c.UpstreamDNS {
		if err := validateUpstream(u); err != nil {
			add("upstreamDns[%d]: %v", i, err)
		}
		if seenUpstream[u] {
			add("upstreamDns[%d]: duplicate %q", i, u)
		}
		seenUpstream[u] = true
	}

	var prefixes []netip.Prefix
	var prevCIDRs []string
	if c.AllowedPrivateCIDRs == nil {
		add("allowedPrivateCidrs: required (use [] for none)")
	}
	seenCIDR := map[string]bool{}
	for i, s := range c.AllowedPrivateCIDRs {
		pfx, err := validateAllowedPrivateCIDR(s)
		if err != nil {
			add("allowedPrivateCidrs[%d]: %v", i, err)
			continue
		}
		if seenCIDR[s] {
			add("allowedPrivateCidrs[%d]: duplicate %q", i, s)
			continue
		}
		seenCIDR[s] = true
		for j, prev := range prefixes {
			if prev.Overlaps(pfx) {
				add("allowedPrivateCidrs[%d]: %q overlaps %q; list each range once", i, s, prevCIDRs[j])
			}
		}
		prefixes = append(prefixes, pfx)
		prevCIDRs = append(prevCIDRs, s)
	}
	ipPolicy := NewIPPolicy(prefixes)

	if c.Callers == nil {
		add("callers: required (use [] for none)")
	} else if len(c.Callers) > maxCallers {
		add("callers: at most %d callers", maxCallers)
	}
	names, ips := map[string]bool{}, map[string]bool{}
	for i, caller := range c.Callers {
		if !callerNamePattern.MatchString(caller.Name) {
			add("callers[%d].name: %q must match %s", i, caller.Name, callerNamePattern)
		}
		if names[caller.Name] {
			add("callers[%d].name: duplicate %q", i, caller.Name)
		}
		names[caller.Name] = true
		if err := validateHostIP(caller.IP); err != nil {
			add("callers[%d].ip: %v", i, err)
		}
		if ips[caller.IP] {
			add("callers[%d].ip: %q is used by another caller", i, caller.IP)
		}
		ips[caller.IP] = true
		if caller.Allow == nil {
			add("callers[%d].allow: required (use [] for none)", i)
		} else if len(caller.Allow) > maxEntries {
			add("callers[%d].allow: at most %d entries", i, maxEntries)
		}
		seen := map[string]bool{}
		for j, s := range caller.Allow {
			e, err := ParseEntry(s)
			if err != nil {
				add("callers[%d].allow[%d]: %v", i, j, err)
				continue
			}
			if e.String() != s {
				add("callers[%d].allow[%d]: %q is not canonical (want %q)", i, j, s, e.String())
			}
			if seen[s] {
				add("callers[%d].allow[%d]: duplicate %q", i, j, s)
			}
			seen[s] = true
			if e.IsIP() {
				if err := ipPolicy.Check(e.IP); err != nil {
					add("callers[%d].allow[%d]: %q can never be reached: %v", i, j, s, err)
				}
			}
		}
	}

	if c.StatsReaders == nil {
		add("statsReaders: required (use [] for none)")
	}
	seenReader := map[string]bool{}
	for i, r := range c.StatsReaders {
		if err := validateHostIP(r); err != nil {
			add("statsReaders[%d]: %v", i, err)
		}
		if seenReader[r] {
			add("statsReaders[%d]: duplicate %q", i, r)
		}
		seenReader[r] = true
	}

	if len(errs) > 0 {
		return fmt.Errorf("invalid egress config: %w", errors.Join(errs...))
	}
	return nil
}

func validateListen(addr string) (string, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return "", fmt.Errorf("%q is not host:port", addr)
	}
	if host != "" {
		ip, err := netip.ParseAddr(host)
		if err != nil || ip.String() != host {
			return "", fmt.Errorf("host in %q must be empty or a canonical IP", addr)
		}
	}
	if port != "0" {
		if _, err := ParsePort(port); err != nil {
			return "", fmt.Errorf("%q has an invalid port", addr)
		}
	}
	return port, nil
}

func validateUpstream(addr string) error {
	ap, err := netip.ParseAddrPort(addr)
	if err != nil {
		return fmt.Errorf("%q must be ip:port", addr)
	}
	if ap.String() != addr || ap.Port() == 0 {
		return fmt.Errorf("%q must be a canonical ip:port with a non-zero port", addr)
	}
	if ap.Addr().IsUnspecified() || ap.Addr().IsMulticast() {
		return fmt.Errorf("%q is not a unicast address", addr)
	}
	return nil
}

func validateHostIP(s string) error {
	ip, err := netip.ParseAddr(s)
	if err != nil || ip.String() != s || ip.Zone() != "" {
		return fmt.Errorf("%q must be a canonical IP address", s)
	}
	if ip.IsUnspecified() || ip.IsMulticast() || ip.Is4In6() {
		return fmt.Errorf("%q must be a unicast address", s)
	}
	return nil
}
